 "content": "def transform(grid):
    """Fill each completely enclosed background cavity: 2x2 cavities with 2, others with 7."""
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                edge |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not edge:
                fill = 2 if len(cells) == 4 else 7
                for y, x in cells:
                    out[y][x] = fill
    return out
